    const { llm, seen } = fakeLlm([
      { type: "text-delta", index: 0, text: "昨天用量集中在 secret-project 与 repo 两个目录。" },
      { type: "usage", usage: { inputTokens: 10, outputTokens: 5, totalTokens: 15 } },
