  it("探针：旧域引用即被 flag", () => {
    const dirty = 'import { parseReportIndexLines } from "../domain2/common/interface.ts";';
    expect(FORBIDDEN_FACES.some((f) => dirty.includes(f))).toBe(true);
  });
});

